ON CONFLICT ("projectId", "slug") DO UPDATE SET "title" = EXCLUDED."title", "kind" = EXCLUDED."kind", "content" = EXCLUDED."content", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();
INSERT INTO project_modules ("id", "projectId", "slug", "title", "kind", "profile", "content", "sortOrder", "updatedAt")
VALUES ('mod_' || substr(md5(random()::text || clock_timestamp()::text), 1, 22), (SELECT id FROM projects WHERE slug = 'dubai-hills-mansion'), 'payment-plan', 'Payment Plan', 'CUSTOM'::"ModuleKind", 'FULL', $json${"text":"Milestones are structured around reservation, progress, handover, and optional post-handover settlement, with final terms confirmed during availability review.","url":"mailto:info@kpd.ae?subject=Dubai%20Hills%20Mansion%20Payment%20Plan","items":[{"value":"15%","label":"On booking","text":"Reservation and initial allocation milestone."},{"value":"35%","label":"During construction","text":"Staged payments aligned to project progress."},{"value":"40%","label":"On completion","text":"Balance due at handover and transfer."},{"value":"10%","label":"After handover","text":"Optional settlement window subject to offer terms."}]}$json$::jsonb, 60, NOW())
ON CONFLICT ("projectId", "slug") DO UPDATE SET "title" = EXCLUDED."title", "kind" = EXCLUDED."kind", "content" = EXCLUDED."content", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = NOW();
DELETE FROM content_versions WHERE "entityType" = 'PROJECT_MODULE' AND "entityId" IN (SELECT id FROM project_modules WHERE "projectId" = (SELECT id FROM projects WHERE slug = 'dubai-hills-mansion') AND slug NOT IN ('dubai-hills-estate', 'location', 'tour', 'amenities', 'brochure', 'floor-plans', 'payment-plan'));
DELETE FROM project_modules WHERE "projectId" = (SELECT id FROM projects WHERE slug = 'dubai-hills-mansion') AND slug NOT IN ('dubai-hills-estate', 'location', 'tour', 'amenities', 'brochure', 'floor-plans', 'payment-plan');

-- 2. Check before committing: every project should list its delivered modules.
SELECT p.slug AS project, m.slug AS module, m."sortOrder" FROM project_modules m JOIN projects p ON p.id = m."projectId" WHERE p.slug IN ('seven-x-seven', 'emerald-villa', 'dubai-hills-mansion') ORDER BY p.slug, m."sortOrder";

COMMIT;

